window.PDD_DATA = {"id":"pdd","title":"ПДД РО","full_title":"ПРАВИЛА ДОРОЖНОГО ДВИЖЕНИЯ РО","revision":"18.09.2026","source_url":"https://forum.russia.online/threads/pravila-dorozhnogo-dvizheniya-ro.5269/","post_id":"post-17428","preamble":"Настоящие Правила устанавливают единый порядок дорожного движения на территории РО и обязательны для водителей, пешеходов, пассажиров, велосипедистов и иных участников дорожного движения.","signature":"Нормативно-правовой акт подписан Премьер-министром РО 18.09.2026 Марк Брагин ​","type_detected":"B","nodes":[{"type":"section","number":"I","title":"ОБЩИЕ ПОЛОЖЕНИЯ","children":[{"type":"chapter","number":"1","title":"Общие положения​","children":[{"type":"article","number":"1.1","title":"Участники дорожного движения обязаны знать и соблюдать относящиеся к ним требова…","children":[{"type":"paragraph","text":"Участники дорожного движения обязаны знать и соблюдать относящиеся к ним требования настоящих Правил, сигналов светофоров и регулировщиков, дорожных знаков и разметки, а также выполнять законные требования сотрудников ГИБДД и иных уполномоченных лиц."}]},{"type":"article","number":"1.2","title":"Настоящие Правила устанавливают требования поведения участников дорожного движен…","children":[{"type":"paragraph","text":"Настоящие Правила устанавливают требования поведения участников дорожного движения и не устанавливают административные наказания. Ответственность за нарушение Правил определяется Кодексом РО об административных правонарушениях и иными федеральными законами."}]},{"type":"article","number":"1.3","title":"Дорожное движение в РО является правосторонним.","children":[{"type":"paragraph","text":"Дорожное движение в РО является правосторонним."}]},{"type":"article","number":"1.4","title":"В настоящих Правилах используются следующие основные понятия:","children":[{"type":"paragraph","text":"В настоящих Правилах используются следующие основные понятия:","children":[{"type":"subparagraph","number":"1","text":"дорога — обустроенная или приспособленная для движения транспортных средств полоса земли либо поверхность искусственного сооружения;"},{"type":"subparagraph","number":"2","text":"проезжая часть — элемент дороги, предназначенный для движения безрельсовых транспортных средств;"},{"type":"subparagraph","number":"3","text":"полоса движения — продольная полоса проезжей части, обозначенная или не обозначенная разметкой и имеющая ширину, достаточную для движения транспортных средств в один ряд;"},{"type":"subparagraph","number":"4","text":"обочина — элемент дороги, примыкающий к проезжей части и не предназначенный для обычного движения транспортных средств;"},{"type":"subparagraph","number":"5","text":"разделительная полоса — конструктивно или разметкой выделенный элемент дороги, разделяющий смежные проезжие части и не предназначенный для движения и остановки;"},{"type":"subparagraph","number":"6","text":"перекресток — место пересечения, примыкания или разветвления дорог на одном уровне;"},{"type":"subparagraph","number":"7","text":"прилегающая территория — территория, непосредственно прилегающая к дороге и не предназначенная для сквозного движения, включая дворы, парковки, территории организаций и заправочных станций;"},{"type":"subparagraph","number":"8","text":"пешеходный переход — участок проезжей части, предназначенный для перехода пешеходов и обозначенный дорожными знаками, разметкой либо светофором;"},{"type":"subparagraph","number":"9","text":"обгон — опережение одного или нескольких транспортных средств, связанное с выездом на полосу встречного движения и последующим возвращением на ранее занимаемую полосу;"},{"type":"subparagraph","number":"10","text":"опережение — движение транспортного средства со скоростью большей скорости попутного транспортного средства без обязательного выезда на встречную полосу;"},{"type":"subparagraph","number":"11","text":"остановка — преднамеренное прекращение движения на время до пяти минут, а также на большее время, если это необходимо для посадки или высадки пассажиров либо загрузки или разгрузки;"},{"type":"subparagraph","number":"12","text":"стоянка — преднамеренное прекращение движения более чем на пять минут по причинам, не связанным с посадкой или высадкой пассажиров либо загрузкой или разгрузкой;"},{"type":"subparagraph","number":"13","text":"уступить дорогу — требование не начинать, не возобновлять и не продолжать движение либо маневр, если это вынудит участника, имеющего преимущество, изменить направление или скорость;"},{"type":"subparagraph","number":"14","text":"дорожно-транспортное происшествие — событие, возникшее в процессе движения транспортного средства с его участием и повлекшее вред человеку либо повреждение транспортного средства, груза, дороги или иного имущества;"},{"type":"subparagraph","number":"15","text":"автомагистраль — дорога, обозначенная соответствующим дорожным знаком и предназначенная для движения с повышенной разрешенной скоростью;"},{"type":"subparagraph","number":"16","text":"организованная транспортная колонна — группа транспортных средств, следующих непосредственно друг за другом по установленному порядку и сопровождаемых уполномоченным государственным транспортным средством;"},{"type":"subparagraph","number":"17","text":"маршрутное транспортное средство — автобус или иное транспортное средство общего пользования, движущееся по установленному маршруту."}]}]},{"type":"article","number":"1.5","title":"Участники движения должны действовать таким образом, чтобы не создавать опасност…","children":[{"type":"paragraph","text":"Участники движения должны действовать таким образом, чтобы не создавать опасности и необоснованных помех другим лицам. Использование предоставленного Правилами преимущества не освобождает от обязанности принимать разумные меры к предотвращению дорожно-транспортного происшествия."}]}]}]},{"type":"section","number":"II","title":"ОБЯЗАННОСТИ ВОДИТЕЛЯ​","children":[{"type":"chapter","number":"2","title":"Общие обязанности водителя","children":[{"type":"article","number":"2.1","title":"Водитель механического транспортного средства обязан иметь действующее право упр…","children":[{"type":"paragraph","text":"Водитель механического транспортного средства обязан иметь действующее право управления транспортным средством соответствующей категории и предъявить по законному требованию сотрудника ГИБДД водительское удостоверение и регистрационные документы на транспортное средство."}]},{"type":"article","number":"2.2","title":"Водитель обязан управлять транспортным средством с установленными и соответствую…","children":[{"type":"paragraph","text":"Водитель обязан управлять транспортным средством с установленными и соответствующими государственному учету регистрационными знаками, если для данного транспортного средства их наличие обязательно."}]},{"type":"article","number":"2.3","title":"Водитель обязан по законному и однозначному требованию сотрудника ГИБДД или иног…","children":[{"type":"paragraph","text":"Водитель обязан по законному и однозначному требованию сотрудника ГИБДД или иного уполномоченного сотрудника полиции остановиться в ближайшем месте, где остановка может быть выполнена безопасно."}]},{"type":"article","number":"2.4","title":"После законной остановки водитель обязан выполнить относящееся к основанию остан…","children":[{"type":"paragraph","text":"После законной остановки водитель обязан выполнить относящееся к основанию остановки законное требование сотрудника, в том числе покинуть транспортное средство, если такое требование предъявлено на предусмотренном федеральным законом основании."}]},{"type":"article","number":"2.5","title":"Водителю запрещается управлять транспортным средством:","children":[{"type":"paragraph","text":"Водителю запрещается управлять транспортным средством:","children":[{"type":"subparagraph","number":"1","text":"в состоянии алкогольного, наркотического или иного опьянения;"},{"type":"subparagraph","number":"2","text":"при отсутствии права управления соответствующей категорией;"},{"type":"subparagraph","number":"3","text":"в болезненном, чрезмерно утомленном или ином состоянии, явно препятствующем безопасному управлению;"},{"type":"subparagraph","number":"4","text":"при технической неисправности, создающей непосредственную угрозу безопасности движения."}]}]},{"type":"article","number":"2.6","title":"Владелец или иной законный пользователь транспортного средства не вправе передав…","children":[{"type":"paragraph","text":"Владелец или иной законный пользователь транспортного средства не вправе передавать управление лицу, заведомо не имеющему права управления соответствующей категорией либо находящемуся в состоянии опьянения."}]},{"type":"article","number":"2.7","title":"При наличии предусмотренных федеральным законом оснований водитель обязан пройти…","children":[{"type":"paragraph","text":"При наличии предусмотренных федеральным законом оснований водитель обязан пройти освидетельствование на состояние опьянения. Порядок освидетельствования определяется федеральным законодательством и Федеральным законом «О Государственной инспекции безопасности дорожного движения»."}]},{"type":"article","number":"2.8","title":"Во время движения водителю запрещается использовать телефон, радиостанцию или ин…","children":[{"type":"paragraph","text":"Во время движения водителю запрещается использовать телефон, радиостанцию или иное средство связи способом, требующим удержания устройства рукой либо существенно отвлекающим от управления. Допускается использование устройств без удержания их рукой, а также использование связи при экстренной необходимости, если водитель принимает разумные меры безопасности."}]},{"type":"article","number":"2.9","title":"Водитель обязан соблюдать безопасную дистанцию, боковой интервал и скорость, поз…","children":[{"type":"paragraph","text":"Водитель обязан соблюдать безопасную дистанцию, боковой интервал и скорость, позволяющие контролировать движение транспортного средства с учетом дорожной обстановки, видимости и состояния дороги."}]},{"type":"article","number":"2.10","title":"Водителю запрещается беспричинно создавать помехи движению чрезмерно низкой скор…","children":[{"type":"paragraph","text":"Водителю запрещается беспричинно создавать помехи движению чрезмерно низкой скоростью, резко тормозить без необходимости, опасно перестраиваться либо последовательно совершать иные маневры, создающие реальную угрозу дорожно-транспортного происшествия."}]},{"type":"article","number":"2.11","title":"Водителю запрещается самовольно вклиниваться в организованную транспортную колон…","children":[{"type":"paragraph","text":"Водителю запрещается самовольно вклиниваться в организованную транспортную колонну, пересекать ее либо препятствовать ее движению."}]}]},{"type":"chapter","number":"3","title":"Обязанности водителя при дорожно-транспортном происшествии","children":[{"type":"article","number":"3.1","title":"Водитель, причастный к дорожно-транспортному происшествию, обязан немедленно ост…","children":[{"type":"paragraph","text":"Водитель, причастный к дорожно-транспортному происшествию, обязан немедленно остановиться, включить аварийную сигнализацию при ее наличии и принять разумные меры для предупреждения других участников движения."}]},{"type":"article","number":"3.2","title":"До фиксации обстоятельств происшествия водитель не должен без необходимости пере…","children":[{"type":"paragraph","text":"До фиксации обстоятельств происшествия водитель не должен без необходимости перемещать транспортное средство, следы и предметы, относящиеся к происшествию. Перемещение допускается для устранения непосредственной угрозы жизни, пожара, нового столкновения либо после достаточной фиксации обстановки."}]},{"type":"article","number":"3.3","title":"При наличии пострадавших водитель обязан:","children":[{"type":"paragraph","text":"При наличии пострадавших водитель обязан:","children":[{"type":"subparagraph","number":"1","text":"принять разумно возможные меры первой помощи;"},{"type":"subparagraph","number":"2","text":"вызвать скорую медицинскую помощь и, при необходимости, иные экстренные службы;"},{"type":"subparagraph","number":"3","text":"сообщить о происшествии в ГИБДД;"},{"type":"subparagraph","number":"4","text":"по возможности сохранить следы происшествия и сведения об очевидцах."}]}]},{"type":"article","number":"3.4","title":"Если вред причинен только имуществу, участники вправе после достаточной фото- ил…","children":[{"type":"paragraph","text":"Если вред причинен только имуществу, участники вправе после достаточной фото- или видеофиксации освободить проезжую часть и добровольно урегулировать имущественный вопрос, если между ними отсутствует существенный спор и федеральный закон не требует участия ГИБДД."}]},{"type":"article","number":"3.5","title":"При споре об обстоятельствах, наличии признаков опьянения, отсутствии права упра…","children":[{"type":"paragraph","text":"При споре об обстоятельствах, наличии признаков опьянения, отсутствии права управления, повреждении государственного имущества либо иных существенных обстоятельствах участники должны сообщить о происшествии в ГИБДД и выполнять законные требования прибывшего сотрудника."}]},{"type":"article","number":"3.6","title":"Водителю запрещается оставлять место дорожно-транспортного происшествия до выпол…","children":[{"type":"paragraph","text":"Водителю запрещается оставлять место дорожно-транспортного происшествия до выполнения обязанностей, установленных настоящим разделом, кроме случаев, когда оставление места вызвано необходимостью немедленно доставить пострадавшего для оказания медицинской помощи либо устранить иную непосредственную опасность."}]},{"type":"article","number":"3.7","title":"После дорожно-транспортного происшествия либо законной остановки, произведенной …","children":[{"type":"paragraph","text":"После дорожно-транспортного происшествия либо законной остановки, произведенной в обстоятельствах, требующих проверки состояния водителя, водителю запрещается употреблять алкогольные, наркотические или иные вызывающие опьянение вещества до проведения необходимого освидетельствования либо принятия решения об отсутствии оснований для него."}]}]}]},{"type":"section","number":"III","title":"СПЕЦИАЛЬНЫЕ СИГНАЛЫ И РЕГУЛИРОВАНИЕ​","children":[{"type":"chapter","number":"4","title":"Применение специальных сигналов","children":[{"type":"article","number":"4.1","title":"Водитель транспортного средства, законно использующего проблесковый маячок синег…","children":[{"type":"paragraph","text":"Водитель транспортного средства, законно использующего проблесковый маячок синего цвета либо синего и красного цветов одновременно с включенным специальным звуковым сигналом при выполнении неотложного служебного задания, вправе отступать от требований разделов 6 (кроме сигналов регулировщика), 7, 8, 9, 10, 11, 17 и 18 настоящих Правил, а также от требований дорожных знаков и разметки, за исключением знаков 2.1 «Главная дорога», 2.2 «Конец главной дороги», 2.4 «Уступите дорогу», 2.5 «Движение без остановки запрещено», знаков особых предписаний, регулирующих движение маршрутных транспортных средств, и знаков, запрещающих въезд на железнодорожный переезд. Отступления от указанных требований допускаются только при обеспечении безопасности движения."}]},{"type":"article","number":"4.2","title":"Для получения преимущества водитель специального транспортного средства обязан в…","children":[{"type":"paragraph","text":"Для получения преимущества водитель специального транспортного средства обязан включить одновременно предусмотренный для него световой и специальный звуковой сигнал, если федеральным законом или характером конкретной задачи не установлено иное."}]},{"type":"article","number":"4.3","title":"Иные водители при приближении транспортного средства, имеющего преимущество по п…","children":[{"type":"paragraph","text":"Иные водители при приближении транспортного средства, имеющего преимущество по пункту 4.1 настоящих Правил, обязаны уступить дорогу и при необходимости снизить скорость или остановиться для обеспечения его беспрепятственного проезда."}]},{"type":"article","number":"4.4","title":"При приближении к стоящему транспортному средству экстренной или государственной…","children":[{"type":"paragraph","text":"При приближении к стоящему транспортному средству экстренной или государственной службы с включенным проблесковым маячком водитель обязан снизить скорость и двигаться с повышенной осторожностью, а при необходимости остановиться."}]},{"type":"article","number":"4.5","title":"Проблесковый маячок желтого или оранжевого цвета не предоставляет преимущества в…","children":[{"type":"paragraph","text":"Проблесковый маячок желтого или оранжевого цвета не предоставляет преимущества в движении и используется для предупреждения об опасности, дорожных работах, перевозке крупногабаритного груза, эвакуации транспортного средства и иных специальных работах."}]},{"type":"article","number":"4.6","title":"Использование специального сигнала не освобождает водителя от ответственности за…","children":[{"type":"paragraph","text":"Использование специального сигнала не освобождает водителя от ответственности за явно опасное или несоразмерное поведение на дороге."}]}]},{"type":"chapter","number":"5","title":"Сигналы светофора и регулировщика","children":[{"type":"article","number":"5.1","title":"Сигналы светофора имеют следующие основные значения:","children":[{"type":"paragraph","text":"Сигналы светофора имеют следующие основные значения:","children":[{"type":"subparagraph","number":"1","text":"зеленый сигнал разрешает движение;"},{"type":"subparagraph","number":"2","text":"мигающий зеленый сигнал разрешает движение и предупреждает о скорой смене сигнала;"},{"type":"subparagraph","number":"3","text":"желтый сигнал запрещает движение, кроме случая, когда водитель не может остановиться без экстренного торможения, и предупреждает о смене сигналов;"},{"type":"subparagraph","number":"4","text":"мигающий желтый сигнал разрешает движение с повышенной осторожностью и означает, что перекресток или переход не регулируется светофором;"},{"type":"subparagraph","number":"5","text":"красный сигнал, в том числе мигающий, запрещает движение;"},{"type":"subparagraph","number":"6","text":"сочетание красного и желтого сигналов запрещает движение и предупреждает о предстоящем включении зеленого сигнала."}]}]},{"type":"article","number":"5.2","title":"При запрещающем сигнале водитель обязан остановиться перед стоп-линией, а при ее…","children":[{"type":"paragraph","text":"При запрещающем сигнале водитель обязан остановиться перед стоп-линией, а при ее отсутствии — перед пересекаемой проезжей частью, пешеходным переходом или светофором таким образом, чтобы не создавать помех."}]},{"type":"article","number":"5.3","title":"Поворот направо или налево на запрещающий основной сигнал допускается только при…","children":[{"type":"paragraph","text":"Поворот направо или налево на запрещающий основной сигнал допускается только при наличии отдельной разрешающей секции, стрелки светофора или временного сигнала регулировщика."}]},{"type":"article","number":"5.4","title":"Если светофор не работает либо подает только мигающий желтый сигнал, участники д…","children":[{"type":"paragraph","text":"Если светофор не работает либо подает только мигающий желтый сигнал, участники движения руководствуются дорожными знаками приоритета и правилами проезда нерегулируемых перекрестков."}]},{"type":"article","number":"5.5","title":"Сигналы регулировщика обязательны для всех участников движения на регулируемом у…","children":[{"type":"paragraph","text":"Сигналы регулировщика обязательны для всех участников движения на регулируемом участке. Регулировщик вправе временно разрешать, ограничивать или запрещать движение жестом, световым сигналом, громкоговорителем либо иным ясно воспринимаемым способом."}]},{"type":"article","number":"5.6","title":"Сигнал регулировщика имеет приоритет перед сигналом светофора, дорожным знаком и…","children":[{"type":"paragraph","text":"Сигнал регулировщика имеет приоритет перед сигналом светофора, дорожным знаком и разметкой в пределах регулируемого участка."}]}]}]},{"type":"section","number":"IV","title":"МАНЕВРИРОВАНИЕ И РАСПОЛОЖЕНИЕ НА ДОРОГЕ​","children":[{"type":"chapter","number":"6","title":"Начало движения и маневрирование","children":[{"type":"article","number":"6.1","title":"Перед началом движения, перестроением, поворотом, разворотом или остановкой води…","children":[{"type":"paragraph","text":"Перед началом движения, перестроением, поворотом, разворотом или остановкой водитель обязан заблаговременно подать соответствующий сигнал световым указателем поворота, а при его неисправности — понятным жестом, если это возможно безопасно."}]},{"type":"article","number":"6.2","title":"Подача сигнала не предоставляет преимущества и не освобождает водителя от обязан…","children":[{"type":"paragraph","text":"Подача сигнала не предоставляет преимущества и не освобождает водителя от обязанности убедиться в безопасности маневра."}]},{"type":"article","number":"6.3","title":"При выезде с прилегающей территории водитель обязан уступить дорогу транспортным…","children":[{"type":"paragraph","text":"При выезде с прилегающей территории водитель обязан уступить дорогу транспортным средствам, велосипедистам и пешеходам, путь движения которых он пересекает. При съезде с дороги водитель обязан уступить дорогу пешеходам и велосипедистам."}]},{"type":"article","number":"6.4","title":"При перестроении водитель обязан уступить дорогу транспортному средству, движуще…","children":[{"type":"paragraph","text":"При перестроении водитель обязан уступить дорогу транспортному средству, движущемуся попутно без изменения направления. При одновременном перестроении преимущество имеет транспортное средство, находящееся справа."}]},{"type":"article","number":"6.5","title":"Перед поворотом направо водитель должен занять крайнее правое положение, а перед…","children":[{"type":"paragraph","text":"Перед поворотом направо водитель должен занять крайнее правое положение, а перед поворотом налево или разворотом — крайнее левое положение на проезжей части данного направления, если дорожные знаки или разметка не устанавливают иной порядок."}]},{"type":"article","number":"6.6","title":"При повороте налево или развороте водитель обязан уступить дорогу встречным тран…","children":[{"type":"paragraph","text":"При повороте налево или развороте водитель обязан уступить дорогу встречным транспортным средствам, движущимся прямо или направо, если иной порядок не установлен сигналом светофора, регулировщика или знаком приоритета."}]},{"type":"article","number":"6.7","title":"Разворот запрещается:","children":[{"type":"paragraph","text":"Разворот запрещается:","children":[{"type":"subparagraph","number":"1","text":"на пешеходных переходах;"},{"type":"subparagraph","number":"2","text":"в тоннелях;"},{"type":"subparagraph","number":"3","text":"на мостах, путепроводах и эстакадах, если маневр создает опасность или прямо запрещен средством организации движения;"},{"type":"subparagraph","number":"4","text":"на железнодорожных переездах;"},{"type":"subparagraph","number":"5","text":"в местах с видимостью дороги хотя бы в одном направлении менее 100 метров;"},{"type":"subparagraph","number":"6","text":"в местах, где разворот запрещен дорожным знаком или разметкой."}]}]},{"type":"article","number":"6.8","title":"Движение задним ходом допускается при условии безопасности и отсутствия помех др…","children":[{"type":"paragraph","text":"Движение задним ходом допускается при условии безопасности и отсутствия помех другим участникам. Оно запрещается на перекрестках, пешеходных переходах, железнодорожных переездах, в тоннелях, на автомагистралях и в иных местах, где такой маневр создает очевидную опасность."}]}]},{"type":"chapter","number":"7","title":"Расположение транспортных средств на проезжей части","children":[{"type":"article","number":"7.1","title":"При отсутствии дорожных знаков и разметки водитель обязан придерживаться правой …","children":[{"type":"paragraph","text":"При отсутствии дорожных знаков и разметки водитель обязан придерживаться правой стороны проезжей части."}]},{"type":"article","number":"7.2","title":"На дороге с несколькими полосами в одном направлении водитель должен по возможно…","children":[{"type":"paragraph","text":"На дороге с несколькими полосами в одном направлении водитель должен по возможности занимать правую свободную полосу. Использование левых полос допускается для опережения, обгона, поворота налево, разворота, объезда препятствия либо при плотном движении."}]},{"type":"article","number":"7.3","title":"На дорогах с двусторонним движением запрещается выезжать на сторону встречного д…","children":[{"type":"paragraph","text":"На дорогах с двусторонним движением запрещается выезжать на сторону встречного движения в местах, где это запрещено разметкой, знаком, условиями видимости либо настоящими Правилами."}]},{"type":"article","number":"7.4","title":"Движение по обочине, разделительной полосе, тротуару, пешеходной или велосипедно…","children":[{"type":"paragraph","text":"Движение по обочине, разделительной полосе, тротуару, пешеходной или велосипедной дорожке механических транспортных средств запрещается, кроме прямо предусмотренных настоящими Правилами случаев, дорожных работ, устранения аварии, подъезда к объекту при отсутствии иного пути либо крайней необходимости."}]},{"type":"article","number":"7.5","title":"Транспортное средство, которое по техническим характеристикам или условиям движе…","children":[{"type":"paragraph","text":"Транспортное средство, которое по техническим характеристикам или условиям движения не может поддерживать обычную скорость потока, должно двигаться как можно правее, если это не препятствует совершению необходимого маневра."}]},{"type":"article","number":"7.6","title":"Водитель обязан соблюдать дорожную разметку, определяющую направления движения п…","children":[{"type":"paragraph","text":"Водитель обязан соблюдать дорожную разметку, определяющую направления движения по полосам, и не занимать полосу, движение по которой не соответствует предполагаемому маневру."}]}]}]},{"type":"section","number":"V","title":"СКОРОСТЬ, ДИСТАНЦИЯ, ОБГОН​","children":[{"type":"chapter","number":"8","title":"Скорость движения","children":[{"type":"article","number":"8.1","title":"Водитель должен вести транспортное средство со скоростью, не превышающей установ…","children":[{"type":"paragraph","text":"Водитель должен вести транспортное средство со скоростью, не превышающей установленного ограничения, учитывая интенсивность движения, особенности транспортного средства и груза, дорожные и погодные условия, видимость и возможность остановиться в пределах обозримого участка дороги."}]},{"type":"article","number":"8.2","title":"Если дорожным знаком не установлено иное, максимальная разрешенная скорость сост…","children":[{"type":"paragraph","text":"Если дорожным знаком не установлено иное, максимальная разрешенная скорость составляет:","children":[{"type":"subparagraph","number":"1","text":"в населенном пункте — 60 км/ч;"},{"type":"subparagraph","number":"2","text":"вне населенного пункта — 90 км/ч;"},{"type":"subparagraph","number":"3","text":"на автомагистрали — 110 км/ч;"},{"type":"subparagraph","number":"4","text":"при буксировке механического транспортного средства — 50 км/ч."}]}]},{"type":"article","number":"8.3","title":"Дорожным знаком может быть установлено иное ограничение скорости для конкретного…","children":[{"type":"paragraph","text":"Дорожным знаком может быть установлено иное ограничение скорости для конкретного участка дороги."}]},{"type":"article","number":"8.4","title":"Для целей применения статьи 52.1 Кодекса РО об административных правонарушениях …","children":[{"type":"paragraph","text":"Для целей применения статьи 52.1 Кодекса РО об административных правонарушениях существенным считается превышение установленной скорости более чем на 20 км/ч."}]},{"type":"article","number":"8.5","title":"Водителю запрещается:","children":[{"type":"paragraph","text":"Водителю запрещается:","children":[{"type":"subparagraph","number":"1","text":"превышать разрешенную скорость;"},{"type":"subparagraph","number":"2","text":"резко снижать скорость без необходимости предотвращения дорожно-транспортного происшествия;"},{"type":"subparagraph","number":"3","text":"создавать необоснованные помехи чрезмерно медленным движением;"},{"type":"subparagraph","number":"4","text":"выбирать скорость, не позволяющую контролировать транспортное средство в конкретных условиях."}]}]}]},{"type":"chapter","number":"9","title":"Обгон и опережение","children":[{"type":"article","number":"9.1","title":"Перед обгоном или опережением водитель обязан убедиться, что полоса движения сво…","children":[{"type":"paragraph","text":"Перед обгоном или опережением водитель обязан убедиться, что полоса движения свободна на достаточном расстоянии, маневр не создаст помех и опасности, а после его завершения возможно безопасно занять полосу движения."}]},{"type":"article","number":"9.2","title":"Водителю обгоняемого транспортного средства запрещается препятствовать обгону ув…","children":[{"type":"paragraph","text":"Водителю обгоняемого транспортного средства запрещается препятствовать обгону увеличением скорости или иными действиями."}]},{"type":"article","number":"9.3","title":"Обгон с выездом на встречную полосу запрещается:","children":[{"type":"paragraph","text":"Обгон с выездом на встречную полосу запрещается:","children":[{"type":"subparagraph","number":"1","text":"если транспортное средство впереди подало сигнал поворота налево и приступило к маневру;"},{"type":"subparagraph","number":"2","text":"на пешеходном переходе;"},{"type":"subparagraph","number":"3","text":"на железнодорожном переезде и непосредственно перед ним;"},{"type":"subparagraph","number":"4","text":"в тоннеле;"},{"type":"subparagraph","number":"5","text":"на мосту, путепроводе или эстакаде, если встречная полоса отделена запрещающей разметкой либо видимость недостаточна;"},{"type":"subparagraph","number":"6","text":"в конце подъема, на опасном повороте и в ином месте с ограниченной видимостью;"},{"type":"subparagraph","number":"7","text":"в месте, где обгон запрещен дорожным знаком или разметкой."}]}]},{"type":"article","number":"9.4","title":"Опережение без выезда на встречную полосу допускается, если оно не запрещено отд…","children":[{"type":"paragraph","text":"Опережение без выезда на встречную полосу допускается, если оно не запрещено отдельным требованием и выполняется безопасно."}]}]}]},{"type":"section","number":"VI","title":"ПРИОРИТЕТ И ПРОЕЗД ПЕРЕКРЕСТКОВ​","children":[{"type":"chapter","number":"10","title":"Общие правила приоритета","children":[{"type":"article","number":"10.1","title":"Приоритет движения определяется сигналами регулировщика, светофора, временными д…","children":[{"type":"paragraph","text":"Приоритет движения определяется сигналами регулировщика, светофора, временными дорожными знаками, постоянными дорожными знаками, дорожной разметкой и настоящими Правилами с учетом установленной настоящими Правилами очередности."}]},{"type":"article","number":"10.2","title":"Водитель, имеющий преимущество, не вправе использовать его таким образом, которы…","children":[{"type":"paragraph","text":"Водитель, имеющий преимущество, не вправе использовать его таким образом, который при очевидной опасности делает дорожно-транспортное происшествие неизбежным."}]},{"type":"article","number":"10.3","title":"При повороте водитель обязан уступить дорогу пешеходам и велосипедистам, пересек…","children":[{"type":"paragraph","text":"При повороте водитель обязан уступить дорогу пешеходам и велосипедистам, пересекающим проезжую часть, на которую он поворачивает."}]},{"type":"article","number":"10.4","title":"В населенном пункте водитель обязан уступить дорогу маршрутному транспортному ср…","children":[{"type":"paragraph","text":"В населенном пункте водитель обязан уступить дорогу маршрутному транспортному средству, начинающему движение от обозначенного места остановки. Водитель маршрутного транспортного средства может начинать движение только убедившись, что ему уступают дорогу."}]}]},{"type":"chapter","number":"11","title":"Проезд перекрестков","children":[{"type":"article","number":"11.1","title":"На регулируемом перекрестке участники движения руководствуются сигналами светофо…","children":[{"type":"paragraph","text":"На регулируемом перекрестке участники движения руководствуются сигналами светофора или регулировщика."}]},{"type":"article","number":"11.2","title":"Водитель, въехавший на перекресток при разрешающем сигнале, должен выехать с нег…","children":[{"type":"paragraph","text":"Водитель, въехавший на перекресток при разрешающем сигнале, должен выехать с него в намеченном направлении независимо от сигнала на выходе, если перед ним не установлена отдельная стоп-линия или светофор, регулирующий конкретное направление."}]},{"type":"article","number":"11.3","title":"Запрещается выезжать на перекресток, если впереди образовался затор, который вын…","children":[{"type":"paragraph","text":"Запрещается выезжать на перекресток, если впереди образовался затор, который вынудит водителя остановиться на пересечении проезжих частей и создать препятствие поперечному движению."}]},{"type":"article","number":"11.4","title":"На нерегулируемом перекрестке неравнозначных дорог водитель, движущийся по второ…","children":[{"type":"paragraph","text":"На нерегулируемом перекрестке неравнозначных дорог водитель, движущийся по второстепенной дороге, обязан уступить транспортным средствам, приближающимся по главной дороге."}]},{"type":"article","number":"11.5","title":"На нерегулируемом перекрестке равнозначных дорог водитель обязан уступить дорогу…","children":[{"type":"paragraph","text":"На нерегулируемом перекрестке равнозначных дорог водитель обязан уступить дорогу транспортному средству, приближающемуся справа."}]},{"type":"article","number":"11.6","title":"При повороте налево или развороте на нерегулируемом перекрестке водитель обязан …","children":[{"type":"paragraph","text":"При повороте налево или развороте на нерегулируемом перекрестке водитель обязан уступить дорогу встречным транспортным средствам, движущимся прямо или направо."}]}]}]},{"type":"section","number":"VII","title":"ПЕШЕХОДЫ, ПАССАЖИРЫ И ВЕЛОСИПЕДИСТЫ​","children":[{"type":"chapter","number":"12","title":"Пешеходы","children":[{"type":"article","number":"12.1","title":"Пешеходы должны двигаться по тротуарам, пешеходным дорожкам либо иным предназнач…","children":[{"type":"paragraph","text":"Пешеходы должны двигаться по тротуарам, пешеходным дорожкам либо иным предназначенным для них участкам. При их отсутствии допускается движение по обочине, а при невозможности — по краю проезжей части с соблюдением мер безопасности."}]},{"type":"article","number":"12.2","title":"Переходить проезжую часть следует по пешеходным переходам, а при их отсутствии в…","children":[{"type":"paragraph","text":"Переходить проезжую часть следует по пешеходным переходам, а при их отсутствии в зоне видимости — на хорошо просматриваемом участке под прямым углом к краю проезжей части после оценки безопасности."}]},{"type":"article","number":"12.3","title":"На регулируемом пешеходном переходе пешеход обязан руководствоваться сигналом пе…","children":[{"type":"paragraph","text":"На регулируемом пешеходном переходе пешеход обязан руководствоваться сигналом пешеходного светофора, а при его отсутствии — транспортного светофора или регулировщика."}]},{"type":"article","number":"12.4","title":"Пешеход не должен без необходимости останавливаться на проезжей части, создавать…","children":[{"type":"paragraph","text":"Пешеход не должен без необходимости останавливаться на проезжей части, создавать умышленные помехи движению либо неожиданно выходить перед близко движущимся транспортным средством."}]},{"type":"article","number":"12.5","title":"При приближении транспортного средства с включенными специальными световым и зву…","children":[{"type":"paragraph","text":"При приближении транспортного средства с включенными специальными световым и звуковым сигналами пешеход обязан воздержаться от выхода на проезжую часть, а находясь на ней — по возможности безопасно освободить путь."}]}]},{"type":"chapter","number":"13","title":"Обязанности водителя перед пешеходами и велосипедистами","children":[{"type":"article","number":"13.1","title":"Водитель обязан уступить дорогу пешеходу, вступившему на нерегулируемый пешеходн…","children":[{"type":"paragraph","text":"Водитель обязан уступить дорогу пешеходу, вступившему на нерегулируемый пешеходный переход или переходящему проезжую часть по нему."}]},{"type":"article","number":"13.2","title":"Если перед пешеходным переходом остановилось или замедлилось транспортное средст…","children":[{"type":"paragraph","text":"Если перед пешеходным переходом остановилось или замедлилось транспортное средство, водители соседних полос вправе продолжить движение только убедившись в отсутствии пешеходов на их пути."}]},{"type":"article","number":"13.3","title":"Водителю запрещается обгон на пешеходном переходе.","children":[{"type":"paragraph","text":"Водителю запрещается обгон на пешеходном переходе."}]},{"type":"article","number":"13.4","title":"При пересечении велосипедной дорожки, выезде с прилегающей территории либо повор…","children":[{"type":"paragraph","text":"При пересечении велосипедной дорожки, выезде с прилегающей территории либо повороте водитель обязан уступить велосипедисту, имеющему преимущество."}]}]},{"type":"chapter","number":"14","title":"Велосипедисты и пассажиры","children":[{"type":"article","number":"14.1","title":"Велосипедист должен двигаться по велосипедной дорожке, а при ее отсутствии — по …","children":[{"type":"paragraph","text":"Велосипедист должен двигаться по велосипедной дорожке, а при ее отсутствии — по правому краю проезжей части или обочине, если это безопасно."}]},{"type":"article","number":"14.2","title":"Велосипедист обязан соблюдать сигналы светофоров, регулировщика, дорожные знаки …","children":[{"type":"paragraph","text":"Велосипедист обязан соблюдать сигналы светофоров, регулировщика, дорожные знаки и требования, относящиеся к направлению его движения."}]},{"type":"article","number":"14.3","title":"При пересечении проезжей части по обычному пешеходному переходу велосипедист дол…","children":[{"type":"paragraph","text":"При пересечении проезжей части по обычному пешеходному переходу велосипедист должен уступать пешеходам и не создавать им помех; при необходимости безопасного перехода он обязан спешиться."}]},{"type":"article","number":"14.4","title":"Пассажир обязан осуществлять посадку и высадку со стороны тротуара или обочины, …","children":[{"type":"paragraph","text":"Пассажир обязан осуществлять посадку и высадку со стороны тротуара или обочины, а если это невозможно — со стороны проезжей части только после убеждения в безопасности."}]},{"type":"article","number":"14.5","title":"Пассажиру запрещается открывать двери транспортного средства, выходить из него и…","children":[{"type":"paragraph","text":"Пассажиру запрещается открывать двери транспортного средства, выходить из него или совершать иные действия, создающие опасность участникам движения."}]}]}]},{"type":"section","number":"VIII","title":"ЖЕЛЕЗНОДОРОЖНЫЕ ПЕРЕЕЗДЫ И АВТОМАГИСТРАЛИ​","children":[{"type":"chapter","number":"15","title":"Движение через железнодорожные пути","children":[{"type":"article","number":"15.1","title":"Пересекать железнодорожные пути разрешается только по оборудованным железнодорож…","children":[{"type":"paragraph","text":"Пересекать железнодорожные пути разрешается только по оборудованным железнодорожным переездам."}]},{"type":"article","number":"15.2","title":"Запрещается выезжать на переезд:","children":[{"type":"paragraph","text":"Запрещается выезжать на переезд:","children":[{"type":"subparagraph","number":"1","text":"при запрещающем сигнале светофора или регулировщика;"},{"type":"subparagraph","number":"2","text":"при закрывающемся или закрытом шлагбауме;"},{"type":"subparagraph","number":"3","text":"если за переездом образовался затор, вынуждающий остановиться на путях;"},{"type":"subparagraph","number":"4","text":"при приближении железнодорожного транспортного средства, когда продолжение движения создает угрозу столкновения."}]}]},{"type":"article","number":"15.3","title":"На железнодорожном переезде запрещаются остановка, стоянка, разворот, движение з…","children":[{"type":"paragraph","text":"На железнодорожном переезде запрещаются остановка, стоянка, разворот, движение задним ходом и обгон."}]},{"type":"article","number":"15.4","title":"При вынужденной остановке на переезде водитель обязан немедленно принять меры к …","children":[{"type":"paragraph","text":"При вынужденной остановке на переезде водитель обязан немедленно принять меры к высадке пассажиров, освобождению путей и предупреждению приближающегося железнодорожного транспорта."}]}]},{"type":"chapter","number":"16","title":"Движение по автомагистралям","children":[{"type":"article","number":"16.1","title":"На автомагистрали запрещается:","children":[{"type":"paragraph","text":"На автомагистрали запрещается:","children":[{"type":"subparagraph","number":"1","text":"движение пешеходов, велосипедов, мопедов и транспортных средств, которые по техническим характеристикам не способны безопасно двигаться со скоростью не менее 40 км/ч;"},{"type":"subparagraph","number":"2","text":"движение задним ходом;"},{"type":"subparagraph","number":"3","text":"разворот и выезд на разделительную полосу;"},{"type":"subparagraph","number":"4","text":"необоснованная остановка вне специально обозначенного места;"},{"type":"subparagraph","number":"5","text":"учебная езда, если она создает препятствие или опасность;"},{"type":"subparagraph","number":"6","text":"движение грузового или медленного транспортного средства по крайней левой полосе без необходимости обгона, объезда или поворота."}]}]},{"type":"article","number":"16.2","title":"При вынужденной остановке на автомагистрали водитель обязан по возможности убрат…","children":[{"type":"paragraph","text":"При вынужденной остановке на автомагистрали водитель обязан по возможности убрать транспортное средство за пределы проезжей части, включить аварийную сигнализацию и обозначить опасность."}]}]}]},{"type":"section","number":"IX","title":"ОСТАНОВКА И СТОЯНКА​","children":[{"type":"chapter","number":"17","title":"Общие правила остановки и стоянки","children":[{"type":"article","number":"17.1","title":"Остановка и стоянка транспортных средств разрешаются на правой стороне дороги у …","children":[{"type":"paragraph","text":"Остановка и стоянка транспортных средств разрешаются на правой стороне дороги у края проезжей части либо на обочине, если дорожными знаками или разметкой не установлен иной порядок."}]},{"type":"article","number":"17.2","title":"На дороге с односторонним движением допускается остановка и стоянка у левого кра…","children":[{"type":"paragraph","text":"На дороге с односторонним движением допускается остановка и стоянка у левого края, если это не запрещено дорожными знаками, разметкой или условиями безопасности."}]},{"type":"article","number":"17.3","title":"Транспортное средство должно быть поставлено в один ряд параллельно краю проезже…","children":[{"type":"paragraph","text":"Транспортное средство должно быть поставлено в один ряд параллельно краю проезжей части, кроме мест, где разметкой, знаком или конфигурацией парковочного места установлен иной способ."}]},{"type":"article","number":"17.4","title":"Остановка запрещается:","children":[{"type":"paragraph","text":"Остановка запрещается:","children":[{"type":"subparagraph","number":"1","text":"на пешеходных переходах;"},{"type":"subparagraph","number":"2","text":"на железнодорожных переездах;"},{"type":"subparagraph","number":"3","text":"в тоннелях;"},{"type":"subparagraph","number":"4","text":"на мостах, путепроводах и эстакадах, если остановка препятствует движению или прямо запрещена;"},{"type":"subparagraph","number":"5","text":"на перекрестке и в месте, где транспортное средство закрывает обзор сигналов, знаков или других участников;"},{"type":"subparagraph","number":"6","text":"в местах остановки маршрутного транспорта, если остановка препятствует его движению;"},{"type":"subparagraph","number":"7","text":"на полосах разгона и торможения;"},{"type":"subparagraph","number":"8","text":"на въездах и выездах с прилегающих территорий, если транспортное средство перекрывает доступ;"},{"type":"subparagraph","number":"9","text":"на тротуаре, если стоянка на нем прямо не разрешена;"},{"type":"subparagraph","number":"10","text":"на служебной парковке государственного органа или иной территории с законно ограниченным доступом без соответствующего разрешения;"},{"type":"subparagraph","number":"11","text":"в иных местах, обозначенных знаком или разметкой «Остановка запрещена»."}]}]},{"type":"article","number":"17.5","title":"Стоянка запрещается во всех местах, где запрещена остановка, а также в местах, о…","children":[{"type":"paragraph","text":"Стоянка запрещается во всех местах, где запрещена остановка, а также в местах, обозначенных знаком или разметкой «Стоянка запрещена»."}]},{"type":"article","number":"17.6","title":"Транспортное средство, остановленное или оставленное с нарушением Правил и созда…","children":[{"type":"paragraph","text":"Транспортное средство, остановленное или оставленное с нарушением Правил и создающее существенную помеху движению, доступу к объекту либо работе экстренных служб, может быть задержано и перемещено в порядке, установленном Кодексом РО об административных правонарушениях."}]}]}]},{"type":"section","number":"X","title":"ВНЕШНИЕ СВЕТОВЫЕ ПРИБОРЫ И ЗВУКОВЫЕ СИГНАЛЫ​","children":[{"type":"chapter","number":"18","title":"Световые приборы","children":[{"type":"article","number":"18.1","title":"В темное время суток, в тоннеле и в условиях недостаточной видимости на движущем…","children":[{"type":"paragraph","text":"В темное время суток, в тоннеле и в условиях недостаточной видимости на движущемся транспортном средстве должны быть включены фары ближнего или дальнего света."}]},{"type":"article","number":"18.2","title":"Дальний свет должен быть переключен на ближний при встречном разъезде и во всех …","children":[{"type":"paragraph","text":"Дальний свет должен быть переключен на ближний при встречном разъезде и во всех иных случаях, когда он может ослепить другого участника движения."}]},{"type":"article","number":"18.3","title":"Аварийная световая сигнализация должна применяться:","children":[{"type":"paragraph","text":"Аварийная световая сигнализация должна применяться:","children":[{"type":"subparagraph","number":"1","text":"при дорожно-транспортном происшествии;"},{"type":"subparagraph","number":"2","text":"при вынужденной остановке в опасном месте;"},{"type":"subparagraph","number":"3","text":"при буксировке на буксируемом транспортном средстве, если это технически возможно;"},{"type":"subparagraph","number":"4","text":"при ослеплении водителя;"},{"type":"subparagraph","number":"5","text":"в иных случаях, когда необходимо предупредить других участников об опасности."}]}]}]},{"type":"chapter","number":"19","title":"Звуковые сигналы","children":[{"type":"article","number":"19.1","title":"Звуковой сигнал допускается для предотвращения дорожно-транспортного происшестви…","children":[{"type":"paragraph","text":"Звуковой сигнал допускается для предотвращения дорожно-транспортного происшествия."}]},{"type":"article","number":"19.2","title":"Вне населенного пункта звуковой сигнал также может кратковременно подаваться для…","children":[{"type":"paragraph","text":"Вне населенного пункта звуковой сигнал также может кратковременно подаваться для предупреждения об обгоне, если это не создает необоснованного беспокойства и не заменяет обязанность обеспечить безопасность маневра."}]},{"type":"article","number":"19.3","title":"Необоснованное длительное или повторное использование звукового сигнала запрещае…","children":[{"type":"paragraph","text":"Необоснованное длительное или повторное использование звукового сигнала запрещается."}]}]}]},{"type":"section","number":"XI","title":"БУКСИРОВКА, ПЕРЕВОЗКА ПАССАЖИРОВ И ГРУЗОВ​","children":[{"type":"chapter","number":"20","title":"Буксировка","children":[{"type":"article","number":"20.1","title":"Буксировка допускается при исправном сцепном устройстве либо ином безопасном спо…","children":[{"type":"paragraph","text":"Буксировка допускается при исправном сцепном устройстве либо ином безопасном способе соединения транспортных средств."}]},{"type":"article","number":"20.2","title":"Максимальная скорость при буксировке составляет 50 км/ч, если дорожным знаком не…","children":[{"type":"paragraph","text":"Максимальная скорость при буксировке составляет 50 км/ч, если дорожным знаком не установлено более низкое ограничение."}]},{"type":"article","number":"20.3","title":"Буксировка запрещается, если техническое состояние транспортного средства, погод…","children":[{"type":"paragraph","text":"Буксировка запрещается, если техническое состояние транспортного средства, погодные условия, способ соединения или дорожная обстановка делают ее явно опасной."}]},{"type":"article","number":"20.4","title":"Буксируемое транспортное средство должно быть обозначено аварийной сигнализацией…","children":[{"type":"paragraph","text":"Буксируемое транспортное средство должно быть обозначено аварийной сигнализацией либо иным доступным способом предупреждения."}]}]},{"type":"chapter","number":"21","title":"Перевозка пассажиров и грузов","children":[{"type":"article","number":"21.1","title":"Водитель обязан перевозить пассажиров таким образом, чтобы они не препятствовали…","children":[{"type":"paragraph","text":"Водитель обязан перевозить пассажиров таким образом, чтобы они не препятствовали управлению и не создавали опасность."}]},{"type":"article","number":"21.2","title":"Запрещается перевозить пассажиров вне предусмотренных конструкцией мест, если та…","children":[{"type":"paragraph","text":"Запрещается перевозить пассажиров вне предусмотренных конструкцией мест, если такой способ создает угрозу их жизни или здоровью."}]},{"type":"article","number":"21.3","title":"Груз должен быть размещен и закреплен так, чтобы он:","children":[{"type":"paragraph","text":"Груз должен быть размещен и закреплен так, чтобы он:","children":[{"type":"subparagraph","number":"1","text":"не ограничивал обзор водителю;"},{"type":"subparagraph","number":"2","text":"не затруднял управление;"},{"type":"subparagraph","number":"3","text":"не закрывал внешние световые приборы и регистрационные знаки;"},{"type":"subparagraph","number":"4","text":"не падал, не волочился и не создавал опасность иным участникам движения."}]}]},{"type":"article","number":"21.4","title":"Если состояние или размещение груза создает опасность, водитель обязан устранить…","children":[{"type":"paragraph","text":"Если состояние или размещение груза создает опасность, водитель обязан устранить нарушение до продолжения движения."}]}]}]},{"type":"section","number":"XII","title":"ТЕХНИЧЕСКОЕ СОСТОЯНИЕ И РЕГИСТРАЦИЯ​","children":[{"type":"chapter","number":"22","title":"Допуск транспортных средств к движению","children":[{"type":"article","number":"22.1","title":"Механическое транспортное средство, для которого установлена обязательная госуда…","children":[{"type":"paragraph","text":"Механическое транспортное средство, для которого установлена обязательная государственная регистрация, допускается к дорожному движению после такой регистрации и с установленными государственными регистрационными знаками."}]},{"type":"article","number":"22.2","title":"Запрещается управление транспортным средством с заведомо подложным, принадлежащи…","children":[{"type":"paragraph","text":"Запрещается управление транспортным средством с заведомо подложным, принадлежащим другому транспортному средству либо умышленно измененным регистрационным знаком."}]},{"type":"article","number":"22.3","title":"Водитель перед началом движения обязан в разумном объеме убедиться в исправности…","children":[{"type":"paragraph","text":"Водитель перед началом движения обязан в разумном объеме убедиться в исправности основных систем транспортного средства."}]},{"type":"article","number":"22.4","title":"Запрещается продолжать движение при неисправности тормозной системы, рулевого уп…","children":[{"type":"paragraph","text":"Запрещается продолжать движение при неисправности тормозной системы, рулевого управления, обязательных световых приборов в условиях, когда они необходимы, либо иной неисправности, создающей непосредственную угрозу безопасности."}]},{"type":"article","number":"22.5","title":"При возникновении в пути неисправности, не создающей непосредственной угрозы и д…","children":[{"type":"paragraph","text":"При возникновении в пути неисправности, не создающей непосредственной угрозы и допускающей безопасное следование к месту ремонта, водитель обязан принять меры предосторожности и устранить неисправность при первой разумной возможности."}]}]}]},{"type":"section","number":"XIII","title":"ДОРОЖНЫЕ ЗНАКИ И РАЗМЕТКА​","children":[{"type":"chapter","number":"23","title":"Общие правила применения знаков и разметки","children":[{"type":"article","number":"23.1","title":"Водители и иные участники движения обязаны соблюдать требования дорожных знаков …","children":[{"type":"paragraph","text":"Водители и иные участники движения обязаны соблюдать требования дорожных знаков и разметки, относящиеся к направлению их движения."}]},{"type":"article","number":"23.2","title":"При временном изменении организации движения временный дорожный знак имеет преим…","children":[{"type":"paragraph","text":"При временном изменении организации движения временный дорожный знак имеет преимущество перед постоянным знаком и разметкой. Сигнал регулировщика имеет преимущество перед любыми дорожными знаками и разметкой."}]},{"type":"article","number":"23.3","title":"При противоречии постоянного дорожного знака и разметки водитель руководствуется…","children":[{"type":"paragraph","text":"При противоречии постоянного дорожного знака и разметки водитель руководствуется дорожным знаком."}]},{"type":"article","number":"23.4","title":"Основные дорожные знаки имеют следующие значения:","children":[{"type":"paragraph","text":"Основные дорожные знаки имеют следующие значения:","children":[{"type":"subparagraph","number":"1","text":"«Уступите дорогу» — водитель обязан уступить транспортным средствам, имеющим преимущество;"},{"type":"subparagraph","number":"2","text":"«Движение без остановки запрещено» («STOP») — водитель обязан полностью остановиться перед стоп-линией, а при ее отсутствии — перед краем пересекаемой проезжей части и уступить дорогу;"},{"type":"subparagraph","number":"3","text":"«Главная дорога» — предоставляет преимущество при проезде нерегулируемого пересечения в пределах действия знака;"},{"type":"subparagraph","number":"4","text":"«Въезд запрещен» — запрещает въезд транспортных средств в данном направлении, кроме прямо предусмотренных исключений;"},{"type":"subparagraph","number":"5","text":"«Движение запрещено» — запрещает движение транспортных средств в зоне действия знака, кроме предусмотренных исключений;"},{"type":"subparagraph","number":"6","text":"«Ограничение максимальной скорости» — запрещает движение со скоростью выше указанной на знаке;"},{"type":"subparagraph","number":"7","text":"«Поворот направо запрещен», «Поворот налево запрещен», «Разворот запрещен» — запрещают соответствующий маневр;"},{"type":"subparagraph","number":"8","text":"«Обгон запрещен» — запрещает обгон с выездом на встречную полосу в зоне действия знака;"},{"type":"subparagraph","number":"9","text":"«Остановка запрещена» — запрещает остановку и стоянку;"},{"type":"subparagraph","number":"10","text":"«Стоянка запрещена» — запрещает стоянку;"},{"type":"subparagraph","number":"11","text":"«Пешеходный переход» — обозначает место перехода пешеходов;"},{"type":"subparagraph","number":"12","text":"«Одностороннее движение» — обозначает дорогу или проезжую часть, по которой движение осуществляется в одном направлении;"},{"type":"subparagraph","number":"13","text":"«Автомагистраль» — обозначает дорогу, на которой действуют требования раздела VIII настоящих Правил;"},{"type":"subparagraph","number":"14","text":"«Полоса для маршрутных транспортных средств» — обозначает полосу, предназначенную преимущественно для маршрутного транспорта."}]}]}]},{"type":"chapter","number":"24","title":"Дорожная разметка","children":[{"type":"article","number":"24.1","title":"Прерывистая линия разметки разделяет полосы движения и может пересекаться при бе…","children":[{"type":"paragraph","text":"Прерывистая линия разметки разделяет полосы движения и может пересекаться при безопасном маневре, если иное не установлено знаком."}]},{"type":"article","number":"24.2","title":"Одинарная или двойная сплошная линия, разделяющая встречные транспортные потоки,…","children":[{"type":"paragraph","text":"Одинарная или двойная сплошная линия, разделяющая встречные транспортные потоки, пересекаться не должна, кроме случая, прямо предусмотренного временной организацией движения, указанием регулировщика или крайней необходимостью."}]},{"type":"article","number":"24.3","title":"Сочетание сплошной и прерывистой линий допускается пересекать со стороны прерыви…","children":[{"type":"paragraph","text":"Сочетание сплошной и прерывистой линий допускается пересекать со стороны прерывистой линии, а со стороны сплошной — только для завершения ранее начатого разрешенного маневра, если это безопасно."}]},{"type":"article","number":"24.4","title":"Сплошная линия, разделяющая попутные полосы либо обозначающая границу участка, п…","children":[{"type":"paragraph","text":"Сплошная линия, разделяющая попутные полосы либо обозначающая границу участка, пересекается только в случаях, прямо разрешенных организацией движения, либо при крайней необходимости."}]},{"type":"article","number":"24.5","title":"Стрелы направлений движения по полосам указывают разрешенные направления маневра…","children":[{"type":"paragraph","text":"Стрелы направлений движения по полосам указывают разрешенные направления маневра из соответствующей полосы."}]},{"type":"article","number":"24.6","title":"Стоп-линия обозначает место обязательной остановки при запрещающем сигнале свето…","children":[{"type":"paragraph","text":"Стоп-линия обозначает место обязательной остановки при запрещающем сигнале светофора, регулировщика или знаке «Движение без остановки запрещено»."}]},{"type":"article","number":"24.7","title":"Разметка пешеходного перехода обозначает участок, на котором пешеходы пользуются…","children":[{"type":"paragraph","text":"Разметка пешеходного перехода обозначает участок, на котором пешеходы пользуются установленным настоящими Правилами преимуществом."}]},{"type":"article","number":"24.8","title":"Желтая линия у края проезжей части или бордюра может обозначать запрет остановки…","children":[{"type":"paragraph","text":"Желтая линия у края проезжей части или бордюра может обозначать запрет остановки либо стоянки в соответствии с примененным видом разметки и дорожным знаком."}]},{"type":"article","number":"24.9","title":"Движение по разделительной полосе и пересечение конструктивно выделенной раздели…","children":[{"type":"paragraph","text":"Движение по разделительной полосе и пересечение конструктивно выделенной разделительной полосы запрещаются, если иное не разрешено организацией движения или регулировщиком."}]}]}]},{"type":"section","number":"XIV","title":"ЗАКЛЮЧИТЕЛЬНЫЕ ПОЛОЖЕНИЯ​","children":[{"type":"chapter","number":"25","title":"Соотношение настоящих Правил с иными актами","children":[{"type":"article","number":"25.1","title":"Полномочия сотрудников ГИБДД по остановке транспортных средств, проверке докумен…","children":[{"type":"paragraph","text":"Полномочия сотрудников ГИБДД по остановке транспортных средств, проверке документов, освидетельствованию, задержанию и перемещению транспортных средств определяются федеральным законодательством и не расширяются настоящими Правилами."}]},{"type":"article","number":"25.2","title":"Порядок привлечения к административной ответственности за нарушение настоящих Пр…","children":[{"type":"paragraph","text":"Порядок привлечения к административной ответственности за нарушение настоящих Правил определяется Кодексом РО об административных правонарушениях."}]},{"type":"article","number":"25.3","title":"Причинение вреда в результате нарушения настоящих Правил может повлечь уголовную…","children":[{"type":"paragraph","text":"Причинение вреда в результате нарушения настоящих Правил может повлечь уголовную, административную или гражданско-правовую ответственность в случаях, установленных федеральным законодательством."}]},{"type":"article","number":"25.4","title":"В случае временного ограничения движения, введенного уполномоченным государствен…","children":[{"type":"paragraph","text":"В случае временного ограничения движения, введенного уполномоченным государственным органом для ликвидации последствий происшествия, проведения специальной операции, государственного мероприятия, дорожных работ либо устранения иной угрозы, участники движения обязаны соблюдать временную схему и законные требования регулирующих лиц."}]},{"type":"article","number":"25.5","title":"Настоящие Правила вступают в силу с момента их официального утверждения Правител…","children":[{"type":"paragraph","text":"Настоящие Правила вступают в силу с момента их официального утверждения Правительством РО."}]}]}]}]};
